/* C API of the Rust port of `src/text.c`, generated by everything-rust. */
#ifndef TEXT_RS_H
#define TEXT_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

size_t count_words(const char *s);
int vowels(const char *s);
bool is_palindrome(const char *s);

/* The same functions under `everything_rust_` names, for shadow runs. */
size_t everything_rust_count_words(const char *s);
int everything_rust_vowels(const char *s);
bool everything_rust_is_palindrome(const char *s);

#endif /* TEXT_RS_H */
